exact_statements.LazyOracleDiscard.commutes_bind:
theorem commutes_bind {σ α β : Type} (L : CacheLens spec σ) {x : StateT σ ProbComp α}
    {f : α → StateT σ ProbComp β} (hx : Commutes L x) (hf : ∀ a, Commutes L (f a)) :
    Commutes L (x >>= f)

definitions.LazyOracleDiscard.Commutes:
def Commutes {σ : Type} (L : CacheLens spec σ) {α : Type} (step : StateT σ ProbComp α) : Prop :=
  ∀ (t : spec.Domain) (s : σ),
    LawEq (L.complete t s >>= step.run) (step.run s >>= fun r => (r.1, ·) <$> L.complete t r.2)

definitions.PqxdhDeploymentHiddenLayout.splitOutput:
def splitOutput (o : PqxdhServerAuthKeySchedule.Output) : Material × PqxdhRecordLiftSeed.Seed :=
  let parts := PqxdhProjectionCollisions.jointKdfStreamProjectionEquiv o.1
  ((parts.1, parts.2.2), (parts.2.1, o.2))

definitions.PqxdhDeploymentHiddenKernels.openPoint:
def openPoint (input : RawCtxWholeOwner.OpenInput) : Option CtxRomAuth.CtxRO.Domain :=
  match RawCtxFrameDecoding.fromPayload input.context.frame.payload with
  | none => none
  | some slices =>
      if input.context.associatedData.length = 153 then some ((), RawCtxSourceOpen.hashInput input slices)
      else none

